  "create_delegation": {
    "precision": "described",
    "operations": [
      "POST /api/v1/delegations 201"
    ],
    "schema": {
      "type": "object",
      "properties": {
        "id": {
          "description": "MongoDB ObjectId"
        },
        "delegation_id": {
          "description": "Stable public handle (`ph_dlg_<32 hex>`) — also the token's `sub`, and accepted by the proof status endpoint"
        },
        "principal": {
          "description": "The proven domain that authorized the delegate — derived from the control proof, never client input"
        },
        "delegate": {
          "description": "Typed delegate identifier"
        },
        "scope": {
          "description": "Deprecated. Delegation schema 2.0 carries no scope; this array stays for the SDKs released before it: the scope a delegation issued before schema 2.0 was stored with, otherwise empty. Removed in the next major version."
        },
        "control_proof": {
          "description": "The control proof handle this delegation points down to"
        },
        "status": {
          "description": "The owner's OWN record — whether they revoked this delegation themselves. Nothing else writes it: neither the control proof dying nor this delegation's own lifetime running out. Liveness is DERIVED and reported separately as `effective_status`. This stored field is also what `?status=` filters on"
        },
        "revoked_at": {},
        "revoked_reason": {},
        "environment": {},
        "issued_at": {},
        "expires_at": {
          "description": "Never later than the control proof's own expiry at issuance (effective expiry is min of the two)"
        },
        "created_at": {},
        "token": {
          "description": "The signed delegation JWT — the PUBLISHABLE artifact (publish it in your MCP server card under `_meta` → `holdings.proof/delegation`). Same key, algorithm and JWKS as proof tokens"
        },
        "effective_status": {
          "description": "DERIVED liveness, computed at read time from BOTH clocks that govern a delegation: the control proof it stands on (cascade rule a — revoked, suspended or expired flows through) and its own `expires_at` (rule b — effective expiry is the earlier of the two). Either one running out reports `expired` here while the delegation's own `status` stays untouched. This is the field to render — `status` alone would show a live badge on a delegation every verifier already rejects"
        },
        "is_valid": {
          "description": "True only when `effective_status` is `active`. It is a restatement of that field, not a second opinion: expiry is decided once, inside the derivation above"
        }
      }
    }
  },
