  "create_identity_challenge": {
    "precision": "proven",
    "operations": [
      "POST /api/v1/identity-challenges 201"
    ],
    "schema": {
      "type": "object",
      "properties": {
        "id": {
          "type": "string"
        },
        "status": {
          "type": "string",
          "description": "The one status every read reports. `pending` — waiting for the person being checked; `confirmed` — they confirmed; `denied` — they denied; `cancelled` — whoever started the check withdrew it; `failed` — the check could not be delivered; `expired` — nobody answered in time; `revoked` / `suspended` — the confirmation's proof was revoked or suspended (`POST /proofs/{proof_id}/revoke` or `/suspend`; revoking a denial's proof leaves it `denied`), or — `revoked` only — the member being checked was removed from the Circle while the check was still pending, which leaves `proof_id` null. Removing a member is not guaranteed to revoke a confirmation they already gave; revoke that one by its `proof_id`. A proof that merely reached its own expiry still reads `confirmed`; whether its token is still valid is `POST /proofs/validate`'s answer."
        },
        "channel": {
          "type": "string",
          "description": "Channel the CONFIRM was dispatched on (GET)"
        },
        "confirm_channel": {
          "type": "string",
          "description": "Channel the CONFIRM was dispatched on (POST)"
        },
        "single_channel_warning": {
          "type": "boolean",
          "description": "True when the account holder has only one channel, so the CONFIRM ran on the same channel as the suspicious contact (degraded)"
        },
        "circle_id": {
          "type": [
            "string",
            "null"
          ],
          "description": "The Circle the check belongs to (GET)"
        },
        "is_drill": {
          "type": "boolean",
          "description": "True for a drill (scheduled, or started from the dashboard) rather than a real check (GET)"
        },
        "proof_id": {
          "type": [
            "string",
            "null"
          ],
          "description": "Public handle of the decision's proof — what `POST /proofs/{proof_id}/revoke` takes. Null until a decision minted one (GET)."
        },
        "proof_token": {
          "type": [
            "string",
            "null"
          ],
          "description": "Signed proof token, present once the person being checked decided"
        },
        "created_at": {
          "type": "string",
          "description": "ISO 8601 timestamp"
        },
        "resolved_at": {
          "type": [
            "string",
            "null"
          ],
          "description": "ISO 8601 timestamp of the decision — the CONFIRM, the DENY, the cancellation or the delivery failure — or null while the check is unanswered and after a timeout."
        },
        "expires_at": {
          "type": "string",
          "description": "ISO 8601 timestamp"
        }
      },
      "required": [
        "id",
        "status"
      ],
      "description": "An identity challenge (Proof of Me)"
    }
  },
